INSERT INTO `clients` VALUES (1,'GLA Online','gla-online',1,'/uploads/clients/1789647821132-gla-logo.webp',1,'GLA University, Mathura (GLA Online) is a premier NAAC A+ accredited and UGC-DEB entitled university offering flexible online UG and PG degree programs including Online MBA, MCA, BBA, BCA, and B.Com with placement support and 0% EMI payment options.','university','online','{\"location\":\"17Km Stone, NH-19, Mathura-Delhi Road, P.O. Chaumuhan, Mathura, Uttar Pradesh 281406\",\"established\":\"2022\",\"naac_grade\":\"A+\",\"meta_title\":\"\",\"meta_description\":\"\",\"programs\":[],\"approvals\":[6],\"affiliations\":[55,143,1],\"rankings\":[8,17,13],\"placement\":{\"highest_package\":\"\",\"average_package\":\"\",\"placement_rate\":\"\"},\"tabs\":[{\"id\":\"1789647298000\",\"title\":\"Overview\",\"slug\":\"overview\",\"content\":\"<h2>GLA University Online - Introduction</h2>\\n\\n<!-- TABLE OF CONTENTS -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4);display:flex;align-items:center;justify-content:center;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\">\\n        <line x1=\\\"8\\\" y1=\\\"6\\\" x2=\\\"21\\\" y2=\\\"6\\\"></line><line x1=\\\"8\\\" y1=\\\"12\\\" x2=\\\"21\\\" y2=\\\"12\\\"></line><line x1=\\\"8\\\" y1=\\\"18\\\" x2=\\\"21\\\" y2=\\\"18\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"6\\\" x2=\\\"3.01\\\" y2=\\\"6\\\"></line><line x1=\\\"3\\\" y1=\\\"12\\\" x2=\\\"3.01\\\" y2=\\\"12\\\"></line><line x1=\\\"3\\\" y1=\\\"18\\\" x2=\\\"3.01\\\" y2=\\\"18\\\"></line>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;\\\">Table of Contents</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;\\\">\\n      <a href=\\\"#introduction\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">1</span>\\n        Introduction\\n      </a>\\n      <a href=\\\"#highlights\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">2</span>\\n        Key Highlights\\n      </a>\\n      <a href=\\\"#ranking\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">3</span>\\n        Ranking &amp; Awards\\n      </a>\\n      <a href=\\\"#program-fees\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">4</span>\\n        Program &amp; Fees\\n      </a>\\n      <a href=\\\"#admission-process\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">5</span>\\n        Admission Process\\n      </a>\\n      <a href=\\\"#placement\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">6</span>\\n        Placement &amp; Career Support\\n      </a>\\n      <a href=\\\"#student-support\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">7</span>\\n        Student Support\\n      </a>\\n      <a href=\\\"#faq\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">8</span>\\n        FAQs\\n      </a>\\n    </div>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- INTRODUCTION -->\\n<div id=\\\"introduction\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path>\\n        <path d=\\\"M2 17l10 5 10-5\\\"></path>\\n        <path d=\\\"M2 12l10 5 10-5\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <div style=\\\"flex:1;min-width:0;\\\">\\n      <div style=\\\"display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;\\\">\\n        <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Introduction</h3>\\n      </div>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA University Online (GLA Online) is the digital learning initiative of GLA University,\\n      <a href=\\\"https://www.collegenirnay.com/universities?city%5B%5D=Mathura&amp;page=1\\\" style=\\\"color:#9B1C2E;text-decoration:none;font-weight:600;\\\">Mathura</a>,\\n      <a href=\\\"https://www.collegenirnay.com/universities?state%5B%5D=Uttar%20Pradesh&amp;page=1\\\" style=\\\"color:#9B1C2E;text-decoration:none;font-weight:600;\\\">Uttar Pradesh</a>, delivered through the university\'s Centre for Distance and Online Education (CDOE). The university was established in the memory of Late Shri Ganeshi Lal Agrawal, and GLA Online extends the university\'s higher-education offerings through online degree programmes. GLA Online is designed for students, working professionals and learners who need flexible access to higher education. This GLA Online overview walks you through accreditation, courses, fees, admission and support, so you have what you need before applying. This GLA University Online overview brings together accreditation details, program structure and support information in one place for prospective students.\\n    </p>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online combines live interactive sessions, recorded lectures, e-books, quizzes, formative assessments, discussion forums and Learning Management System (LMS) access. GLA University is <b>NAAC A+ accredited</b>, and its online programmes are offered through the CDOE under the UGC online-education framework. The current GLA Online portfolio includes programmes in management, computer applications and commerce.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:0 0 16px;justify-content:center;\\\">\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\">\\n          <span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">NAAC A+</span>\\n        </div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Accredited</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\">\\n          <span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">5</span>\\n        </div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Online Degree Programs</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\">\\n          <span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">51,000+</span>\\n        </div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Alumni</div>\\n      </div>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 14px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online currently offers <b>Online MBA, Online MCA, Online BBA, Online BCA and Online B.Com. (Hons.)</b>. The MBA and BBA programmes also offer multiple specializations, including areas such as Banking &amp; Financial Services, Business Analytics, Operations Management, Supply Chain Management, Finance Management, Human Resource Management, Information Technology Management and Marketing Management for MBA, and Financial Management, Human Resource Management, Marketing Management and Business Logistics &amp; Supply Chain Management for BBA.\\n    </p>\\n  </div>\\n</div>\\n\\n<!-- KEY HIGHLIGHTS -->\\n<div id=\\\"highlights\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(201,146,42,0.9),rgba(217,164,65,0.8),rgba(236,200,121,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(201,146,42,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M12 2L15 8l6 .9-4.5 4.3L18 20l-6-3-6 3 1.5-6.8L3 8.9 9 8z\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Key Highlights</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      The table below covers the essentials every applicant should know before going deeper into <b>GLA Online</b> — from accreditation status to fees and the range of <b>GLA University online courses</b> on offer. This GLA University Online overview table highlights accreditation, fees and GLA University online courses at a glance so applicants can compare options quickly.\\n    </p>\\n\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:360px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;width:40%;\\\">Category</th>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;\\\">Details</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">University</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">GLA University Online, offered through the Centre for Distance and Online Education (CDOE)</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Location</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">GLA University, Mathura, Uttar Pradesh</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Accreditation</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">GLA University is NAAC A+ accredited with a score of 3.46; the university\'s UGC-DEB documentation lists NAAC validity up to January 23, 2028.</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Regulatory Status</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">UGC-recognized online degree programmes offered by GLA University through its online education framework; GLA\'s official disclosures include UGC-DEB approval documentation for its online programmes.</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">GLA Online Courses</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">5 programs — MBA, MCA, BBA, BCA and B.Com. (Hons.)</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">GLA Online Fees</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">Approx. ₹20,000–₹48,500 per year in recurring course fees depending on program, plus applicable examination, registration and alumni fees (see Program &amp; Fees below).</td>\\n          </tr>\\n          <tr onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Alumni</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">51,000+ alumni across the GLA University network.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- RANKING & AWARDS -->\\n<div id=\\\"ranking\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(201,146,42,0.9),rgba(217,164,65,0.8),rgba(236,200,121,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(201,146,42,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M12 2L15 8l6 .9-4.5 4.3L18 20l-6-3-6 3 1.5-6.8L3 8.9 9 8z\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;\\\">Ranking &amp; Awards</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA University has built its academic profile through accreditation, national rankings and international rankings. The current GLA Online website lists the university in the QS World University Rankings 2026, the Times Higher Education World University Rankings 2026, and the NIRF 2025 rankings, alongside its <b>NAAC A+ accreditation</b> and other institutional recognitions.\\n    </p>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      To be precise about terminology: the NAAC A+ accreditation applies to GLA University as the higher educational institution, while its online degree programmes are offered through GLA University\'s online education division under the applicable UGC framework. GLA University\'s UGC-DEB documentation records Section 2(f) recognition and an A+ NAAC grade with a score of 3.46.\\n    </p>\\n\\n    <div id=\\\"rcr\\\" style=\\\"display:flex;flex-wrap:wrap;gap:20px;padding:12px 16px 8px;\\\">\\n      <img src=\\\"x\\\" onerror=\\\"(function(el){function a(){var r=document.getElementById(\'rcr\');if(!r)return;var cards=r.querySelectorAll(\'[data-card]\');var m=window.innerWidth&lt;=768;if(m){r.style.gap=\'12px\';r.style.padding=\'12px\';for(var i=0;i&lt;cards.length;i++){cards[i].style.width=\'calc(50% - 6px)\';cards[i].style.minWidth=\'0\';cards[i].style.boxSizing=\'border-box\';}}else{r.style.gap=\'20px\';r.style.padding=\'12px 16px 8px\';for(var i=0;i&lt;cards.length;i++){cards[i].style.width=\'145px\';cards[i].style.minWidth=\'145px\';}}}a();window.addEventListener(\'resize\',a);el.parentNode.removeChild(el);})(this)\\\" style=\\\"display:none;\\\" alt=\\\"\\\">\\n\\n      <div data-card=\\\"1\\\" style=\\\"background:#F9F6F1;border:1px solid #f3d9dd;border-top:3px solid #7a1625;border-radius:8px;padding:16px 12px;text-align:left;width:145px;min-width:145px;display:inline-flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;transition:transform 0.3s ease,box-shadow 0.3s ease,border-color 0.3s ease;\\\" onmouseover=\\\"this.style.transform=\'translateY(-5px)\';this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.12)\';this.style.borderColor=\'#7a1625\';\\\" onmouseout=\\\"this.style.transform=\'translateY(0)\';this.style.boxShadow=\'none\';this.style.borderColor=\'#f3d9dd\';\\\">\\n        <img src=\\\"https://collegekeycms.geduconnect.in/uploads/Untitled_3_5452858af2.webp\\\" alt=\\\"NAAC\\\" style=\\\"height:44px;width:44px;object-fit:contain;margin-bottom:10px;display:block;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#241014;line-height:1.5;font-weight:600;word-break:break-word;white-space:normal;width:100%;text-align:left;\\\">NAAC <span style=\\\"color:#14070b;font-weight:700;\\\">A+</span> Accredited</p>\\n      </div>\\n\\n      <div data-card=\\\"1\\\" style=\\\"background:#F9F6F1;border:1px solid #f3d9dd;border-top:3px solid #7a1625;border-radius:8px;padding:16px 12px;text-align:left;width:145px;min-width:145px;display:inline-flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;transition:transform 0.3s ease,box-shadow 0.3s ease,border-color 0.3s ease;\\\" onmouseover=\\\"this.style.transform=\'translateY(-5px)\';this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.12)\';this.style.borderColor=\'#7a1625\';\\\" onmouseout=\\\"this.style.transform=\'translateY(0)\';this.style.boxShadow=\'none\';this.style.borderColor=\'#f3d9dd\';\\\">\\n        <img src=\\\"https://collegekeycms.geduconnect.in/uploads/NAAC_f2cfa7ba49.webp\\\" alt=\\\"NAAC Score\\\" style=\\\"height:44px;width:44px;object-fit:contain;margin-bottom:10px;display:block;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#241014;line-height:1.5;font-weight:600;word-break:break-word;white-space:normal;width:100%;text-align:left;\\\">NAAC Accreditation Score: <span style=\\\"color:#14070b;font-weight:700;\\\">3.46</span></p>\\n      </div>\\n\\n      <div data-card=\\\"1\\\" style=\\\"background:#F9F6F1;border:1px solid #f3d9dd;border-top:3px solid #7a1625;border-radius:8px;padding:16px 12px;text-align:left;width:145px;min-width:145px;display:inline-flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;transition:transform 0.3s ease,box-shadow 0.3s ease,border-color 0.3s ease;\\\" onmouseover=\\\"this.style.transform=\'translateY(-5px)\';this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.12)\';this.style.borderColor=\'#7a1625\';\\\" onmouseout=\\\"this.style.transform=\'translateY(0)\';this.style.boxShadow=\'none\';this.style.borderColor=\'#f3d9dd\';\\\">\\n        <img src=\\\"https://collegekeycms.geduconnect.in/uploads/NAAC_f2cfa7ba49.webp\\\" alt=\\\"NAAC Validity\\\" style=\\\"height:44px;width:44px;object-fit:contain;margin-bottom:10px;display:block;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#241014;line-height:1.5;font-weight:600;word-break:break-word;white-space:normal;width:100%;text-align:left;\\\">NAAC Accreditation Valid Until: <span style=\\\"color:#14070b;font-weight:700;\\\">January 23, 2028</span></p>\\n      </div>\\n\\n      <div data-card=\\\"1\\\" style=\\\"background:#F9F6F1;border:1px solid #f3d9dd;border-top:3px solid #7a1625;border-radius:8px;padding:16px 12px;text-align:left;width:145px;min-width:145px;display:inline-flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;transition:transform 0.3s ease,box-shadow 0.3s ease,border-color 0.3s ease;\\\" onmouseover=\\\"this.style.transform=\'translateY(-5px)\';this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.12)\';this.style.borderColor=\'#7a1625\';\\\" onmouseout=\\\"this.style.transform=\'translateY(0)\';this.style.boxShadow=\'none\';this.style.borderColor=\'#f3d9dd\';\\\">\\n        <img src=\\\"https://collegekeycms.geduconnect.in/uploads/UGC_cb044da01e.webp\\\" alt=\\\"UGC\\\" style=\\\"height:44px;width:44px;object-fit:contain;margin-bottom:10px;display:block;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#241014;line-height:1.5;font-weight:600;word-break:break-word;white-space:normal;width:100%;text-align:left;\\\">UGC Recognition: <span style=\\\"color:#14070b;font-weight:700;\\\">Section 2(f)</span> of the UGC Act, 1956</p>\\n      </div>\\n\\n      <div data-card=\\\"1\\\" style=\\\"background:#F9F6F1;border:1px solid #f3d9dd;border-top:3px solid #7a1625;border-radius:8px;padding:16px 12px;text-align:left;width:145px;min-width:145px;display:inline-flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;box-sizing:border-box;transition:transform 0.3s ease,box-shadow 0.3s ease,border-color 0.3s ease;\\\" onmouseover=\\\"this.style.transform=\'translateY(-5px)\';this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.12)\';this.style.borderColor=\'#7a1625\';\\\" onmouseout=\\\"this.style.transform=\'translateY(0)\';this.style.boxShadow=\'none\';this.style.borderColor=\'#f3d9dd\';\\\">\\n        <img src=\\\"https://collegekeycms.geduconnect.in/uploads/UGC_cb044da01e.webp\\\" alt=\\\"UGC\\\" style=\\\"height:44px;width:44px;object-fit:contain;margin-bottom:10px;display:block;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#241014;line-height:1.5;font-weight:600;word-break:break-word;white-space:normal;width:100%;text-align:left;\\\"><span style=\\\"color:#14070b;font-weight:700;\\\">UGC-recognized</span> Online Degree Programs</p>\\n      </div>\\n\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:14px 0;\\\"></div>\\n\\n    <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:16px 18px;\\\">\\n      <p style=\\\"margin:0 0 8px;font-weight:700;color:#0D1B2A;font-size:14px;\\\">GLA Online NAAC Grade &amp; UGC Status, in Plain Terms</p>\\n      <p style=\\\"margin:0;line-height:1.7;font-size:13.5px;color:#241014;\\\">\\n        The GLA Online NAAC grade that applicants ask about refers to the parent institution, GLA University, which is accredited with an A+ grade by NAAC and has a recorded score of 3.46. GLA Online delivers its online degree programmes through the university\'s Centre for Distance and Online Education, with the programmes offered under the applicable UGC online-education recognition framework.\\n      </p>\\n    </div>\\n  </div>\\n</div>\\n\\n<!-- PROGRAM & FEES -->\\n<div id=\\\"program-fees\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M9 11l3 3L22 4\\\"></path>\\n        <path d=\\\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Program &amp; Fees</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online offers undergraduate and postgraduate degree programs in management, computer applications and commerce, delivered through the university\'s LMS with live interactive sessions, recorded lectures, e-books, quizzes, formative assessments and discussion forums. This section covers GLA Online courses and fees so you know what to expect before applying to any GLA University online courses.\\n    </p>\\n\\n    <h4>Program &amp; Fee Facts</h4>\\n\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n<li style=\\\"word-break:break-word;\\\"><b>Undergraduate programs:</b> Online BBA, Online BCA and Online B.Com. (Hons.)</li>\\n\\n<li style=\\\"word-break:break-word;\\\"><b>Postgraduate programs:</b> Online MBA and Online MCA</li>\\n\\n<li style=\\\"word-break:break-word;\\\"><b>Specialized programs:</b> MBA specializations in Banking &amp; Financial Services, Business Analytics, Operations Management, Supply Chain Management, Finance Management, Human Resource Management, Information Technology Management and Marketing Management; BBA specializations include Financial Management, Human Resource Management, Marketing Management and Business Logistics &amp; Supply Chain Management.</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Learning mode:</b> Online through LMS-based live sessions, recorded lectures, e-books, quizzes, formative assessments and discussion forums</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Fee payment:</b> Semester, annual or full-program payment options are available depending on the program, with applicable fee benefits and no-cost EMI options on eligible payment plans.</li>\\n    </ul>\\n\\n    <h4 style=\\\"margin-bottom:8px;\\\">Approximate Program Fees</h4>\\n    <p style=\\\"font-size:12.5px;color:#6b7280;margin:0 0 10px;\\\">Figures below are based on the current GLA Online fee structure — confirm the applicable amount, fee benefits and examination charges before publishing or applying.</p>\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:360px;margin-bottom:14px;\\\">\\n        <thead><tr>\\n          <th style=\\\"text-align:center;padding:12px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Program</th>\\n          <th style=\\\"text-align:center;padding:12px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Duration</th>\\n          <th style=\\\"text-align:center;padding:12px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Approx. Annual Course Fee</th>\\n        </tr></thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\"><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online BBA</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">3 Years</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹29,500*</td></tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\"><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online BCA</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">3 Years</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹29,500*</td></tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\"><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online B.Com. (Hons.)</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">3 Years</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹20,000*</td></tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\"><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online MBA</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">2 Years</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹48,500*</td></tr>\\n          <tr style=\\\"background:#ffffff;\\\"><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online MCA</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">2 Years</td><td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹43,000*</td></tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <p style=\\\"font-size:12.5px;color:#6b7280;margin:0 0 14px;\\\">*The figures above are the recurring annual course/tuition fees published by GLA Online. Additional one-time registration and alumni fees and examination fees apply. The current published structure lists registration and alumni charges of ₹500 and ₹1,800 respectively, while examination fees vary by payment mode and programme. GLA Online exam fees and the GLA Online exam schedule should be confirmed directly with the university before each semester.</p>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online fees vary by course, payment plan and applicable fee benefits. The current published total course fees are ₹97,000 for MBA, ₹86,000 for MCA, ₹88,500 for BBA, ₹88,500 for BCA and ₹60,000 for B.Com. (Hons.), before applicable one-time charges and according to the fee structure displayed by GLA Online.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/gla-university-online/program-fees\\\" style=\\\"display:inline-block;background:#9B1C2E;color:#ffffff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">Check GLA Online Programs &amp; Fees →</a>\\n  </div>\\n</div>\\n\\n<!-- ADMISSION PROCESS -->\\n<div id=\\\"admission-process\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(217,164,65,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\\\"></path>\\n        <polyline points=\\\"9 22 9 12 15 12 15 22\\\"></polyline>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Admission Process</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online follows a fully digital admission process: eligible candidates choose a program, register online, complete the registration form, pay the registration fee, undergo document verification and then pay the admission fee without needing to visit the university for the application process.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:0 0 16px;justify-content:center;\\\">\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(13px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">100%</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Application Mode</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(13px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">Eligibility-Based</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Selection Basis</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(13px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">Digital</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Document Upload</div>\\n      </div>\\n    </div>\\n\\n    <h4>Admission Process Facts</h4>\\n\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 1:</b> Select the preferred online program and complete the initial registration</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 2:</b> Fill in personal, residential and academic details, complete the registration form and upload the required documents</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 3:</b> Pay the registration fee, complete document verification and pay the applicable admission fee to secure admission</li>\\n    </ul>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Undergraduate programs generally require Class 12 or an equivalent qualification from a recognized board. MBA applicants must hold a bachelor\'s degree from a recognized university, while MCA applicants must hold a bachelor\'s degree, preferably with a background in Science, Computer Applications or Information Technology. Final-year undergraduate applicants awaiting results may also apply to the postgraduate programmes according to the current eligibility information. Learners also complete the GLA Online exam process each semester as part of continuous academic assessment.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/gla-university-online/admission-process\\\" style=\\\"display:inline-block;background:#9B1C2E;color:#ffffff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">Check GLA Online Admission Process →</a>\\n  </div>\\n</div>\\n\\n<!-- PLACEMENT & CAREER SUPPORT -->\\n<div id=\\\"placement\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <circle cx=\\\"12\\\" cy=\\\"8\\\" r=\\\"6\\\"></circle>\\n        <path d=\\\"M15.477 12.89L17 22l-5-3-5 3 1.523-9.11\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Placement &amp; Career Support</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online follows a career-oriented approach that supports learners with career development and placement assistance, including resume building, interview preparation, access to job portals and participation in recruitment drives. The current GLA Online website also highlights a network of 3,000+ recruiters across the broader GLA ecosystem.\\n    </p>\\n\\n    <h4>Placement &amp; Career Support Facts</h4>\\n\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\"><b>Career assistance:</b> Resume building, interview preparation, career development and job-portal access for online learners</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Industry readiness:</b> Interactive learning, practical coursework and career-focused support</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Recruitment network:</b> The university\'s current online website highlights 3,000+ recruiters across its ecosystem.</li>\\n    </ul>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:8px;margin-bottom:4px;\\\">\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#9B1C2E;border:1px solid rgba(137, 44, 64, .14);\\\">Career Guidance</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#9B1C2E;border:1px solid rgba(137, 44, 64, .14);\\\">Interview Preparation</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#9B1C2E;border:1px solid rgba(137, 44, 64, .14);\\\">Skill Development</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#9B1C2E;border:1px solid rgba(137, 44, 64, .14);\\\">Recruitment Drives</span>\\n    </div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Placement and career outcomes depend on the selected program, specialization, previous experience, academic performance, skills and recruitment conditions — no individual job, salary or placement outcome should be considered guaranteed. GLA Online itself states that it provides placement readiness and career-growth assistance, not a guaranteed job placement.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/gla-university-online/placements-career-support\\\" style=\\\"display:inline-block;background:#9B1C2E;color:#ffffff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">Explore GLA Online Placement &amp; Career Support →</a>\\n  </div>\\n</div>\\n\\n<!-- STUDENT SUPPORT -->\\n<div id=\\\"student-support\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <rect x=\\\"2\\\" y=\\\"7\\\" width=\\\"20\\\" height=\\\"14\\\" rx=\\\"2\\\"></rect>\\n        <path d=\\\"M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2\\\"></path>\\n        <line x1=\\\"12\\\" y1=\\\"12\\\" x2=\\\"12\\\" y2=\\\"16\\\"></line>\\n        <line x1=\\\"10\\\" y1=\\\"14\\\" x2=\\\"14\\\" y2=\\\"14\\\"></line>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Student Support</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      GLA Online provides academic and technical support so learners can manage their studies remotely, with LMS access to live classes, recorded sessions, e-books, quizzes, formative assessments and discussion forums. This part of the GLA Online overview shows how GLA Online supports learners studying from different locations and working professionals balancing education with other responsibilities.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:0 0 16px;justify-content:center;\\\">\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">LMS</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Learning Access</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">Live + Recorded</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Online Classes</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;box-sizing:border-box;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">Online</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Learner Assistance</div>\\n      </div>\\n    </div>\\n\\n    <h4>Student Support Facts</h4>\\n\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\">Live interactive sessions and recorded lectures support flexible learning and revision</li>\\n\\n      <li style=\\\"word-break:break-word;\\\">E-books, quizzes, formative assessments and discussion forums are available through the LMS</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Academic support:</b> Dedicated Program Coordinator, doubt-clearing sessions, discussion forums and continuous academic mentoring</li>\\n\\n      <li style=\\\"word-break:break-word;\\\"><b>Technical support:</b> Assistance for LMS access, login and other learner-support queries through the university\'s support channels</li>\\n    </ul>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      The online support system is designed for learners studying from different locations and for working professionals balancing education with other responsibilities. GLA Online states that live classes are usually conducted on weekends, while recordings remain available through the LMS for learners who miss a live session.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/gla-university-online/student-support\\\" style=\\\"display:inline-block;background:#9B1C2E;color:#ffffff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">Explore GLA Online Student Support →</a>\\n  </div>\\n</div>\\n\\n<!-- FAQs -->\\n<div id=\\\"faq\\\" style=\\\"scroll-margin-top:30vh;background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"></circle><path d=\\\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\\\"></path><line x1=\\\"12\\\" y1=\\\"17\\\" x2=\\\"12.01\\\" y2=\\\"17\\\"></line></svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">FAQs</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <!-- FAQ 1 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">1</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">What is GLA University Online?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA University Online, commonly branded as GLA Online, is the online learning initiative of GLA University, Mathura, delivered through its Centre for Distance and Online Education (CDOE). It offers online undergraduate and postgraduate degree programs through live classes, recorded lectures and LMS-based study resources. This GLA University Online overview also covers the GLA Online exam pattern, accreditation and fee details before you apply.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 2 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">2</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Is GLA Online UGC approved?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online states that its online programmes are recognized by the University Grants Commission (UGC), with degrees awarded through approved online programmes treated in accordance with UGC regulations. GLA University\'s UGC-DEB documentation records Section 2(f) recognition and the university maintains UGC-DEB approval disclosures for its online programmes.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 3 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">3</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Which GLA Online courses are available?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online currently offers 5 online degree programmes — Online MBA, Online MCA, Online BBA, Online BCA and Online B.Com. (Hons.). MBA and BBA are available with multiple specialization options.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 4 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">4</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">How much are GLA Online fees?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        The current published recurring course fees are approximately ₹48,500 per year for MBA, ₹43,000 per year for MCA, ₹29,500 per year for BBA, ₹29,500 per year for BCA and ₹20,000 per year for B.Com. (Hons.). Additional registration, alumni and examination fees apply, and GLA Online also publishes full-programme fee figures and payment benefits.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 5 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">5</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Where is GLA Online located?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online is associated with GLA University, Mathura, Uttar Pradesh, whose campus is located at 17 Km Stone, NH-19, Delhi-Mathura Road, P.O. Chaumuhan, Mathura-281406, Uttar Pradesh, India. Since the programmes are online, learners can study remotely without relocating to Mathura for regular classes.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 6 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">6</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Is a GLA Online degree valid?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online states that degrees awarded through its approved online programmes are valid and hold equivalence to regular on-campus degrees in accordance with UGC regulations. The exact use of a degree can still depend on the eligibility rules of the employer, institution, regulatory body or further-study programme involved.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 7 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">7</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">What is the GLA Online NAAC grade?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        There is no separate NAAC grade for the online division. The relevant institutional NAAC grade is GLA University\'s A+ accreditation, with a recorded score of 3.46 in its UGC-DEB documentation. That accreditation applies to the university as the higher educational institution offering the online programmes through its CDOE.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 8 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">8</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">What is the eligibility for GLA Online admission?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        Undergraduate GLA Online courses generally require completion of Class 12 or an equivalent qualification from a recognized board. MBA applicants must hold a bachelor\'s degree from a recognized university, while MCA applicants must hold a bachelor\'s degree, preferably with a Science, Computer Applications or IT background. Eligibility requirements differ across GLA University online courses, so applicants should confirm the criteria for their selected program before applying.\\n      </div>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:20px 0 0;\\\"></div>\\n  </div>\\n</div>\"},{\"id\":\"1789647298552\",\"title\":\"Program & fees\",\"slug\":\"program-fees\",\"content\":\"<!-- GLA ONLINE FEES -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path><path d=\\\"M2 17l10 5 10-5\\\"></path><path d=\\\"M2 12l10 5 10-5\\\"></path></svg>\\n    </div>\\n    <div style=\\\"flex:1;min-width:0;\\\">\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">GLA University Online — Courses &amp; Fees 2026</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      This <b>GLA Online courses and fees</b> guide covers <b>GLA Online UG courses</b> and <b>GLA Online PG courses</b> offered through the Centre for Distance and Online Education (CDOE), with the full <b>GLA Online fee</b> breakdown for every program. Below you will find detailed <b>GLA Online program fees</b> for each course, including the <b>Tuition Fee</b>, <b>Exam Fee</b>, <b>Alumni Fee</b>, applicable <b>Discount</b>, and the <b>Total Fee Payable</b>, covering <b>GLA Online BBA fees</b>, <b>GLA Online B.Com fees</b>, <b>GLA Online BCA fees</b>, <b>GLA Online MBA fees</b>, and <b>GLA Online MCA fees</b>. Students should confirm the latest applicable <b>GLA University Online fees</b>, discount eligibility, and payment schedule before enrolling, as amounts may vary by admission cycle. This GLA Online fee structure lists the complete course list of GLA University Online programs, and covers the GLA University fees structure for each of the five degree programs offered.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:14px;\\\">\\n\\n      <!-- BBA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#9B1C2E;margin-bottom:6px;\\\">Online BBA · 3 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#241014;margin-bottom:10px;\\\">BBA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#ffffff;color:#9B1C2E;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137, 44, 64, .14);\\\">Reg. Fee ₹500</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#7a1f2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #f3d9dd;\\\">₹29,500/yr</span>\\n          <span style=\\\"display:inline-block;background:#F9F6F1;color:#5f1d2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #ecc879;\\\">Total ₹99,800</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#ffffff;text-decoration:none;font-weight:600;background:#9B1C2E;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#9B1C2E;text-decoration:none;font-weight:600;background:#ffffff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137, 44, 64, .14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n      <!-- B.Com -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#9B1C2E;margin-bottom:6px;\\\">Online B.Com · 3 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#241014;margin-bottom:10px;\\\">B.Com. (Hons.)</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#ffffff;color:#9B1C2E;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137, 44, 64, .14);\\\">Reg. Fee ₹500</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#7a1f2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #f3d9dd;\\\">₹20,000/yr</span>\\n          <span style=\\\"display:inline-block;background:#F9F6F1;color:#5f1d2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #ecc879;\\\">Total ₹71,300</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#ffffff;text-decoration:none;font-weight:600;background:#9B1C2E;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#9B1C2E;text-decoration:none;font-weight:600;background:#ffffff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137, 44, 64, .14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n      <!-- BCA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#9B1C2E;margin-bottom:6px;\\\">Online BCA · 3 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#241014;margin-bottom:10px;\\\">BCA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#ffffff;color:#9B1C2E;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137, 44, 64, .14);\\\">Reg. Fee ₹500</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#7a1f2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #f3d9dd;\\\">₹29,500/yr</span>\\n          <span style=\\\"display:inline-block;background:#F9F6F1;color:#5f1d2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #ecc879;\\\">Total ₹99,800</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#ffffff;text-decoration:none;font-weight:600;background:#9B1C2E;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#9B1C2E;text-decoration:none;font-weight:600;background:#ffffff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137, 44, 64, .14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n      <!-- MBA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#9B1C2E;margin-bottom:6px;\\\">Online MBA · 2 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#241014;margin-bottom:10px;\\\">MBA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#ffffff;color:#9B1C2E;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137, 44, 64, .14);\\\">Reg. Fee ₹500</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#7a1f2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #f3d9dd;\\\">₹48,500/yr</span>\\n          <span style=\\\"display:inline-block;background:#F9F6F1;color:#5f1d2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #ecc879;\\\">Total ₹1,05,300</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#ffffff;text-decoration:none;font-weight:600;background:#9B1C2E;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#9B1C2E;text-decoration:none;font-weight:600;background:#ffffff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137, 44, 64, .14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n      <!-- MCA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#9B1C2E;margin-bottom:6px;\\\">Online MCA · 2 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#241014;margin-bottom:10px;\\\">MCA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#ffffff;color:#9B1C2E;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137, 44, 64, .14);\\\">Reg. Fee ₹500</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#7a1f2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #f3d9dd;\\\">₹43,000/yr</span>\\n          <span style=\\\"display:inline-block;background:#F9F6F1;color:#5f1d2b;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid #ecc879;\\\">Total ₹94,300</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#ffffff;text-decoration:none;font-weight:600;background:#9B1C2E;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#9B1C2E;text-decoration:none;font-weight:600;background:#ffffff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137, 44, 64, .14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n</div>\\n    <div style=\\\"overflow-x:auto;margin-top:20px;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:640px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">S. No.</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Course</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Registration Fee</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Tuition Fee</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Exam Fee</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Alumni Fee</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Total Fee</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Discount</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Fee Payable after Discount</th>\\n            <th style=\\\"text-align:center;padding:12px 14px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:12px;text-transform:uppercase;\\\">Total Fee (incl. Registration Fee)</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\">\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">1</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;font-weight:600;\\\">BBA</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹88,500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹9,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹99,300</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹3,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹96,300</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹99,800</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\">\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">2</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;font-weight:600;\\\">B.Com</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹60,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹9,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹70,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹3,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹67,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹71,300</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\">\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">3</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;font-weight:600;\\\">BCA</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹88,500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹9,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹99,300</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹3,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹96,300</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹99,800</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\">\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">4</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;font-weight:600;\\\">MBA</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹97,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹6,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,04,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹4,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,00,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,05,300</td>\\n          </tr>\\n          <tr>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">5</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;font-weight:600;\\\">MCA</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹500</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹86,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹6,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹1,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹93,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹4,000</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹89,800</td>\\n            <td style=\\\"padding:11px 14px;font-size:13px;text-align:center;\\\">₹94,300</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;margin-top:18px;\\\">\\n      Note: Fees shown above under this <b>GLA Online courses and fees</b> guide include the Registration Fee, Tuition Fee, Exam Fee and Alumni Fee, with the applicable Discount already reflected in the Fee Payable after Discount column. The final <b>Total Fee (including Registration Fee)</b> figure represents the complete amount payable for the program. Applicants comparing <b>GLA Online UG courses</b> against <b>GLA Online PG courses</b> should verify the latest <b>GLA Online program fees</b> structure before payment. This complete course list of GLA University courses reflects the current GLA University Online MBA fees structure and the broader GLA University fees structure applicable across all programs.\\n    </p>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:20px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- FAQs -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(201,146,42,0.9),rgba(217,164,65,0.8),rgba(236,200,121,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(201,146,42,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"></circle><path d=\\\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\\\"></path><line x1=\\\"12\\\" y1=\\\"17\\\" x2=\\\"12.01\\\" y2=\\\"17\\\"></line>\\n      </svg>\\n    </div>\\n    <div style=\\\"flex:1;min-width:0;\\\">\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">FAQs — GLA Online Courses &amp; Fees</h3>\\n    </div>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <!-- FAQ 1 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">1</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">What are the GLA Online fees for undergraduate programs?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online BBA fees and GLA Online BCA fees carry a Total Fee of ₹99,300 each (Tuition ₹88,500 + Exam ₹9,000 + Alumni ₹1,800), reduced to ₹96,300 after the applicable ₹3,000 discount. GLA Online B.Com fees are lower, with a Total Fee of ₹70,800 (Tuition ₹60,000 + Exam ₹9,000 + Alumni ₹1,800), reduced to ₹67,800 after the ₹3,000 discount. Each program also carries a separate ₹500 registration fee. This part of the GLA Online fee structure is drawn from the same course list of GLA University courses used across the GLA University fees structure page.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 2 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">2</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">What are the GLA Online MBA fees and GLA Online MCA fees?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        GLA Online MBA fees add up to a Total Fee of ₹1,04,800 (Tuition ₹97,000 + Exam ₹6,000 + Alumni ₹1,800), reduced to ₹1,00,800 after a ₹4,000 discount, or ₹1,05,300 including the ₹500 registration fee. GLA Online MCA fees add up to a Total Fee of ₹93,800 (Tuition ₹86,000 + Exam ₹6,000 + Alumni ₹1,800), reduced to ₹89,800 after the same ₹4,000 discount, or ₹94,300 including registration. These figures form part of the GLA University Online MBA fees structure and the wider GLA Online fee structure covering GLA University courses.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 3 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">3</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Is the registration fee included in the Total Fee shown for each GLA Online course?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        No, the ₹500 registration fee shown for every GLA Online course is separate from the Total Fee (Tuition + Exam + Alumni Fee) and the Fee Payable after Discount. The final \\\"Total Fee (including Registration Fee)\\\" column in the fee table adds the ₹500 registration charge to the Fee Payable after Discount to give the complete amount due.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 4 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">4</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Which GLA Online course has the highest total fee?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        Among all GLA Online programs, the MBA carries the highest Total Fee (including Registration Fee) at ₹1,05,300, followed by MCA at ₹94,300. Among the undergraduate programs, BBA and BCA carry the highest total at ₹99,800 each, while B.Com. (Hons.) has the lowest total at ₹71,300.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 5 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);\\\" onmouseover=\\\"this.style.background=\'#F9F6F1\';this.style.boxShadow=\'0 6px 24px rgba(137,44,64,0.13)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.style.boxShadow=\'0 2px 8px rgba(137,44,64,0.07)\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#F9F6F1\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:clamp(12px,3vw,16px) clamp(12px,3vw,20px);display:flex;align-items:center;gap:clamp(10px,2vw,14px);cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:clamp(30px,5vw,36px);height:clamp(30px,5vw,36px);background:#F9F6F1;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:clamp(12px,2.5vw,14px);font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">5</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#241014;line-height:1.4;flex:1;\\\">Can the GLA Online fees or discount change after admission?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:clamp(16px,3vw,20px);\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 clamp(12px,3vw,20px) 0 clamp(52px,10vw,70px);font-size:clamp(12px,2vw,14px);color:#6b7280;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        The GLA Online fee figures shown here, including the applicable discount, are indicative and may be revised by admission cycle. Applicants are advised to verify the latest GLA University Online fees and discount eligibility directly before making payment. Any revision to the GLA University Online MBA fees structure or other program fees is reflected in the updated GLA Online fee structure published on this page.\\n      </div>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:20px 0 0;\\\"></div>\\n  </div>\\n</div>\"},{\"id\":\"1789647299120\",\"title\":\"Admission Process\",\"slug\":\"admission-process\",\"content\":\"<style>\\n  html { scroll-behavior: smooth; }\\n  summary::-webkit-details-marker { display: none; }\\n</style>\\n\\n<h2 style=\\\"margin-bottom:20px;color:#241014;line-height:1.3;\\\">Ganeshi Lal Agrawal University Online – Admission Process</h2>\\n\\n<!-- INTRODUCTION -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path><path d=\\\"M2 17l10 5 10-5\\\"></path><path d=\\\"M2 12l10 5 10-5\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Introduction</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      <b>GLA University Online admission</b> for undergraduate and postgraduate programs through the Centre for Distance and Online Education (CDOE) is currently open for online degree programs including Online BBA, Online BCA, Online B.Com. (Hons.), Online MBA and Online MCA. The <b>Ganeshi Lal Agrawal University Online admission</b> process allows students and working professionals to apply for these degree programs without needing to visit the campus. GLA Online\'s current admission portal lists MBA, MCA, BBA, BCA and B.Com. (Hons.) as its online degree offerings.\\n    </p>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      The entire <b>GLA University Online admission process</b> is conducted digitally — from registration and email verification to filling the registration form, document submission, registration-fee payment, verification and admission-fee payment. Candidates can <b>GLA University Online apply online</b> through the official GLA Online admission portal and complete the admission process remotely.\\n    </p>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Before applying, candidates are advised to check the <b>GLA University Online eligibility</b> criteria for their preferred program, along with the list of <b>GLA University Online documents required</b> for verification. The official eligibility page specifies separate requirements for MBA, MCA, BBA, BCA and B.Com. (Hons.). Before starting the GLA admission form, applicants should also review the GLA University admission process outlined in this guide, since GLA Online Admission 2026 follows the same document-based verification steps described here.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- TABLE OF CONTENTS -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4);display:flex;align-items:center;justify-content:center;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\">\\n        <line x1=\\\"8\\\" y1=\\\"6\\\" x2=\\\"21\\\" y2=\\\"6\\\"></line><line x1=\\\"8\\\" y1=\\\"12\\\" x2=\\\"21\\\" y2=\\\"12\\\"></line><line x1=\\\"8\\\" y1=\\\"18\\\" x2=\\\"21\\\" y2=\\\"18\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"6\\\" x2=\\\"3.01\\\" y2=\\\"6\\\"></line><line x1=\\\"3\\\" y1=\\\"12\\\" x2=\\\"3.01\\\" y2=\\\"12\\\"></line><line x1=\\\"3\\\" y1=\\\"18\\\" x2=\\\"3.01\\\" y2=\\\"18\\\"></line>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;\\\">Table of Contents</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;\\\">\\n      <a href=\\\"#highlights\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">1</span>\\n        Admission Highlights 2026\\n      </a>\\n      <a href=\\\"#programs\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">2</span>\\n        Online Programs Offered\\n      </a>\\n      <a href=\\\"#eligibility\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">3</span>\\n        Eligibility &amp; Selection\\n      </a>\\n      <a href=\\\"#process\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">4</span>\\n        Step-by-Step Admission Process\\n      </a>\\n      <a href=\\\"#documents\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">5</span>\\n        Documents Required\\n      </a>\\n      <a href=\\\"#dates\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">6</span>\\n        Important Dates\\n      </a>\\n      <a href=\\\"#faq\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">7</span>\\n        FAQs\\n      </a>\\n    </div>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- ADMISSION HIGHLIGHTS -->\\n<div id=\\\"highlights\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(201,146,42,0.9),rgba(217,164,65,0.8),rgba(236,200,121,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(201,146,42,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M12 2L15 8l6 .9-4.5 4.3L18 20l-6-3-6 3 1.5-6.8L3 8.9 9 8z\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Admission Highlights 2026</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:360px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;width:38%;\\\">Category</th>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;\\\">Details</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Program</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">Ganeshi Lal Agrawal University Online admission (GLA Online, CDOE)</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Mode of Admission</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">100% Online — candidates can GLA University Online apply online from registration through fee payment.</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Programs Offered</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">Online BBA, BCA, B.Com. (Hons.), MBA and MCA.</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Basis of Selection</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">Eligibility-based admission, subject to meeting the prescribed academic requirements for the selected program. The current official admission pages do not state a separate entrance examination requirement for these programs. GLA Online Admission 2026 follows the same eligibility-based GLA University admission process across all five online programs.</td>\\n          </tr>\\n          <tr onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Application Mode</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#241014;\\\">Online — submit your GLA University Online application through the official admission portal.</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- ONLINE PROGRAMS OFFERED -->\\n<div id=\\\"programs\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\\\"></path><path d=\\\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Online Programs Offered</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Students seeking <b>GLA University Online admission</b> can choose from undergraduate and postgraduate online degrees. Current programs include <b>GLA University Online BBA admission</b> and <b>GLA University Online BCA admission</b> at the undergraduate level, along with <b>GLA University Online MBA admission</b> and <b>GLA University Online MCA admission</b> at the postgraduate level.\\n    </p>\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\"><b>Undergraduate:</b> Online BBA, Online BCA and Online B.Com. (Hons.) — candidates can apply for the undergraduate program that matches their academic background and career goals</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Postgraduate:</b> Candidates pursuing GLA University Online MBA admission or GLA University Online MCA admission must meet the respective eligibility criteria before applying</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Other PG Options:</b> Online MCA is the postgraduate computer-application option currently listed by GLA Online, while Online MBA is the management degree currently offered</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Specialized MBA:</b> Online MBA is available with specializations including Banking and Financial Services, Business Analytics, Operations Management, Supply Chain Management, Finance Management, Human Resource Management, Information Technology Management and Marketing Management</li>\\n    </ul>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Applicants completing the application form for any of these programs go through the same GLA University admission process regardless of specialization.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- ELIGIBILITY & SELECTION -->\\n<div id=\\\"eligibility\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(217,164,65,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <path d=\\\"M9 11l3 3L22 4\\\"></path><path d=\\\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">GLA University Online Eligibility &amp; Selection Criteria</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Every applicant must satisfy the <b>GLA University Online admission eligibility</b> conditions listed below before submitting an application. The <b>GLA University Online eligibility</b> requirements differ for undergraduate and postgraduate programs.\\n    </p>\\n\\n    <h4 style=\\\"margin:0 0 10px;color:#241014;font-size:14px;font-weight:700;\\\">Undergraduate Programs — GLA University Online Eligibility</h4>\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:480px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Program</th>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Eligibility Criteria</th>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Selection Basis</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Online BBA</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;border-right:1px solid #faf8f9;\\\">10+2 or equivalent from a recognized board in any stream</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;\\\">Eligibility-based</td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Online BCA</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;border-right:1px solid #faf8f9;\\\">10+2 or equivalent from a recognized board in any stream; no prior coding experience is required</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;\\\">Eligibility-based</td>\\n          </tr>\\n          <tr onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Online B.Com. (Hons.)</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;border-right:1px solid #faf8f9;\\\">10+2 or equivalent from a recognized board in any stream</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;\\\">Eligibility-based</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;margin-top:12px;\\\">\\n      The official GLA Online eligibility page states that BBA, BCA and B.Com. (Hons.) applicants can come from any academic stream, subject to the stated 10+2/equivalent qualification.\\n    </p>\\n\\n    <h4 style=\\\"margin:16px 0 10px;color:#14070b;font-size:14px;font-weight:700;\\\">Postgraduate Programs — GLA University Online Admission Eligibility</h4>\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:480px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Program</th>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Eligibility Criteria</th>\\n            <th style=\\\"text-align:center;padding:13px 16px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.03em;text-transform:uppercase;\\\">Selection Basis</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Online MBA</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;border-right:1px solid #faf8f9;\\\">Bachelor\'s degree in any discipline from a recognized university</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;\\\">Eligibility-based</td>\\n          </tr>\\n          <tr onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Online MCA</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;border-right:1px solid #faf8f9;\\\">Bachelor\'s degree from a recognized university, preferably with a background in Science, Computer Applications or Information Technology (IT)</td>\\n            <td style=\\\"padding:12px 16px;font-size:13.5px;color:#241014;\\\">Eligibility-based</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;margin-top:12px;\\\">\\n      The official GLA Online eligibility page also states that final-year undergraduate students awaiting their results can apply for the MBA and MCA programs, subject to the applicable admission requirements.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- STEP-BY-STEP ADMISSION PROCESS -->\\n<div id=\\\"process\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <polyline points=\\\"9 11 12 14 22 4\\\"></polyline><path d=\\\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Step-by-Step GLA University Online Admission Process</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      The <b>GLA University Online admission process</b> is designed to be simple and fully digital. Follow the steps below to complete your <b>GLA University Online application</b> without a campus visit. Filling out the application form correctly at each step of the GLA admission form submission helps avoid delays during GLA Online Admission 2026.\\n    </p>\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 1:</b> Visit the official GLA Online admission portal, enter the required basic details and begin the GLA University Online admission process by registering with your details</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 2:</b> Verify your email and use the login credentials provided to access the registration portal, then complete the registration form with your personal, parent/guardian, residential and academic information</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 3:</b> Upload the GLA University Online documents required for identity and academic verification, including the documents and undertaking specified by the university</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 4:</b> Pay the applicable registration fee to proceed with your GLA University Online application. The current GLA Online FAQ lists a non-refundable registration fee of ₹2,000</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 5:</b> Complete document verification and satisfy the applicable GLA University Online admission eligibility requirements</li>\\n      <li style=\\\"word-break:break-word;\\\"><b>Step 6:</b> Pay the applicable admission fee to finalize your Ganeshi Lal Agrawal University Online admission</li>\\n    </ul>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- DOCUMENTS REQUIRED -->\\n<div id=\\\"documents\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <rect x=\\\"2\\\" y=\\\"7\\\" width=\\\"20\\\" height=\\\"14\\\" rx=\\\"2\\\"></rect><path d=\\\"M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2\\\"></path>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">GLA University Online Documents Required</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      Candidates should keep the following <b>GLA University Online documents required</b> list ready in digital format before starting their application, as incomplete submissions may delay the admission and verification process. The current GLA Online FAQ specifies the following documents.\\n    </p>\\n    <ul style=\\\"padding-left:18px;line-height:1.7;word-spacing:normal;\\\">\\n      <li style=\\\"word-break:break-word;\\\">Recent passport-size photograph</li>\\n      <li style=\\\"word-break:break-word;\\\">Valid government-issued ID proof (Aadhaar Card)</li>\\n      <li style=\\\"word-break:break-word;\\\">Undertaking form</li>\\n      <li style=\\\"word-break:break-word;\\\">Digital signature</li>\\n      <li style=\\\"word-break:break-word;\\\">Class 10th and 12th mark sheets (for undergraduate programs)</li>\\n      <li style=\\\"word-break:break-word;\\\">Graduation certificate and mark sheets (for postgraduate programs including GLA University Online MBA admission and GLA University Online MCA admission)</li>\\n    </ul>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      All GLA University Online documents required must be submitted in the manner specified through the admission process. The university may require additional information or verification where applicable. Keeping these documents ready in advance makes completing the application form and the GLA admission form significantly faster.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- IMPORTANT DATES -->\\n<div id=\\\"dates\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <rect x=\\\"3\\\" y=\\\"4\\\" width=\\\"18\\\" height=\\\"18\\\" rx=\\\"2\\\" ry=\\\"2\\\"></rect><line x1=\\\"16\\\" y1=\\\"2\\\" x2=\\\"16\\\" y2=\\\"6\\\"></line><line x1=\\\"8\\\" y1=\\\"2\\\" x2=\\\"8\\\" y2=\\\"6\\\"></line><line x1=\\\"3\\\" y1=\\\"10\\\" x2=\\\"21\\\" y2=\\\"10\\\"></line>\\n      </svg>\\n    </div>\\n   <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Important Dates</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <div style=\\\"overflow-x:auto;\\\">\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:320px;\\\">\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;width:55%;\\\">Event</th>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:linear-gradient(135deg,#9B1C2E,#c9922a);color:#ffffff;font-weight:700;font-size:13px;letter-spacing:0.04em;text-transform:uppercase;\\\">Date</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">GLA Online Application Opens</td>\\n            <td style=\\\"padding:13px 20px;\\\"><span style=\\\"color:#241014;font-weight:700;padding:3px 12px;border-radius:20px;font-size:13px;white-space:nowrap;\\\">April 2026</span></td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Last Date to Apply Online</td>\\n            <td style=\\\"padding:13px 20px;\\\"><span style=\\\"color:#241014;font-weight:700;padding:3px 12px;border-radius:20px;font-size:13px;white-space:nowrap;\\\">October 2026</span></td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Document Verification</td>\\n            <td style=\\\"padding:13px 20px;\\\"><span style=\\\"color:#241014;font-weight:700;padding:3px 12px;border-radius:20px;font-size:13px;white-space:nowrap;\\\">October 2026</span></td>\\n          </tr>\\n          <tr style=\\\"border-bottom:1px solid #faf8f9;background:#faf8f9;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#faf8f9\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Admission Confirmation</td>\\n            <td style=\\\"padding:13px 20px;\\\"><span style=\\\"color:#241014;font-weight:700;padding:3px 12px;border-radius:20px;font-size:13px;white-space:nowrap;\\\">October 2026</span></td>\\n          </tr>\\n          <tr onmouseover=\\\"this.style.background=\'#fdf0f2\'\\\" onmouseout=\\\"this.style.background=\'#ffffff\'\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#0D1B2A;border-right:1px solid #faf8f9;\\\">Academic Session Begins</td>\\n            <td style=\\\"padding:13px 20px;\\\"><span style=\\\"color:#241014;font-weight:700;padding:3px 12px;border-radius:20px;font-size:13px;white-space:nowrap;\\\">October 2026</span></td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;margin:14px 0 0;font-size:13px;color:#5f1d2b;background:#F9F6F1;border-left:4px solid #c9922a;padding:10px 14px;border-radius:0 8px 8px 0;\\\">\\n      <strong>Note:</strong> The current official GLA Online application portal states \\\"Admissions Open,\\\" but the official pages reviewed do not publish a fixed 2026 last date, document-verification date or academic-session start date. Therefore, specific dates should not be stated as confirmed unless GLA University publishes them in its current admission notice or academic calendar.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- FAQs -->\\n<div id=\\\"faq\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(201,146,42,0.9),rgba(217,164,65,0.8),rgba(236,200,121,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(201,146,42,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\">\\n        <circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"></circle><path d=\\\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\\\"></path><line x1=\\\"12\\\" y1=\\\"17\\\" x2=\\\"12.01\\\" y2=\\\"17\\\"></line>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">FAQs</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <!-- FAQ 1 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#f3d9dd\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:14px 20px;display:flex;align-items:center;gap:12px;cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:32px;height:32px;background:#f3d9dd;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">1</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#0D1B2A;line-height:1.4;flex:1;\\\">How do I start the GLA University Online admission process?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:20px;\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 20px 0 64px;font-size:13.5px;color:#241014;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        Visit the official GLA Online website or admission portal and select Apply Now. Register by providing the required details, verify your email, log in using the credentials provided, complete the registration form, upload the required documents and pay the registration fee. After document verification, pay the applicable admission fee to complete the GLA University Online admission process.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 2 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#f3d9dd\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:14px 20px;display:flex;align-items:center;gap:12px;cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:32px;height:32px;background:#f3d9dd;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">2</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#0D1B2A;line-height:1.4;flex:1;\\\">What is the GLA University Online eligibility for MBA and MCA programs?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:20px;\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 20px 0 64px;font-size:13.5px;color:#241014;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        For GLA University Online MBA admission, candidates need a bachelor\'s degree in any discipline from a recognized university. For GLA University Online MCA admission, candidates need a bachelor\'s degree from a recognized university, preferably with a Science, Computer Applications or Information Technology background. The current official eligibility page also states that final-year undergraduate students awaiting results can apply for these postgraduate programs.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 3 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);margin-bottom:10px;\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#f3d9dd\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:14px 20px;display:flex;align-items:center;gap:12px;cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:32px;height:32px;background:#f3d9dd;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">3</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#0D1B2A;line-height:1.4;flex:1;\\\">What documents are needed to complete my GLA University Online application?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:20px;\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 20px 0 64px;font-size:13.5px;color:#241014;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        The GLA University Online documents required include a recent passport-size photograph, Aadhaar Card or valid government-issued ID as specified, undertaking form, digital signature, Class 10th and 12th mark sheets for undergraduate applicants, and graduation certificate and mark sheets for postgraduate applicants.\\n      </div>\\n    </div>\\n\\n    <!-- FAQ 4 -->\\n    <div style=\\\"border-radius:12px;overflow:hidden;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-top:4px solid #9B1C2E;box-shadow:0 2px 8px rgba(137,44,64,0.07);\\\" onmouseover=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'400px\';this.querySelector(\'.faq-answer\').style.opacity=\'1\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'18px\';this.querySelector(\'.faq-num\').style.background=\'#9B1C2E\';this.querySelector(\'.faq-num\').style.color=\'#ffffff\';\\\" onmouseout=\\\"this.style.background=\'#fdf0f2\';this.querySelector(\'.faq-answer\').style.maxHeight=\'0\';this.querySelector(\'.faq-answer\').style.opacity=\'0\';this.querySelector(\'.faq-answer\').style.paddingBottom=\'0\';this.querySelector(\'.faq-num\').style.background=\'#f3d9dd\';this.querySelector(\'.faq-num\').style.color=\'#9B1C2E\';\\\">\\n      <div style=\\\"padding:14px 20px;display:flex;align-items:center;gap:12px;cursor:pointer;\\\">\\n        <span class=\\\"faq-num\\\" style=\\\"flex-shrink:0;width:32px;height:32px;background:#f3d9dd;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#9B1C2E;transition:all 0.3s;\\\">4</span>\\n        <span style=\\\"font-weight:600;font-size:clamp(13px,2.5vw,15px);color:#0D1B2A;line-height:1.4;flex:1;\\\">Is Ganeshi Lal Agrawal University Online admission recognized?</span>\\n        <span style=\\\"flex-shrink:0;color:rgba(137, 44, 64, .14);font-size:20px;\\\">›</span>\\n      </div>\\n      <div class=\\\"faq-answer\\\" style=\\\"max-height:0;opacity:0;overflow:hidden;padding:0 20px 0 64px;font-size:13.5px;color:#241014;line-height:1.8;transition:max-height 0.4s ease,opacity 0.35s ease,padding-bottom 0.3s ease;\\\">\\n        Yes. GLA Online states that its online programs are recognized by the University Grants Commission (UGC), and degrees awarded through approved online programs are considered equivalent to regular on-campus degrees in accordance with UGC regulations. GLA University\'s online admission and mandatory-disclosure pages also publish its UGC/DEB documentation and online-program disclosures.\\n      </div>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\"},{\"id\":\"1789647299504\",\"title\":\"Placements & Career Support\",\"slug\":\"placements-career-support\",\"content\":\"<style>\\n  html { scroll-behavior: smooth; }\\n  summary::-webkit-details-marker { display: none; }\\n</style>\\n\\n<h2 style=\\\"margin-bottom:20px;color:#241014;line-height:1.3;\\\">GLA University Online — Placements &amp; Career Support</h2>\\n\\n<!-- INTRODUCTION -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path><path d=\\\"M2 17l10 5 10-5\\\"></path><path d=\\\"M2 12l10 5 10-5\\\"></path></svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Introduction</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      <b>GLA Online placement</b> support is built to help online learners translate their degrees into real career opportunities. Through structured <b>GLA Online career support</b>, students enrolled in undergraduate and postgraduate programs receive placement assistance, career counselling, and guidance designed to help them prepare for employment — all delivered digitally alongside their coursework. GLA Online\'s official FAQ states that eligible learners can access career advisory and placement assistance services, while the university\'s online programmes also highlight placements powered by GLA University.\\n    </p>\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      <b>GLA University Online placement</b> services are designed for working professionals and online learners alike, making career support accessible alongside flexible digital study. From <b>GLA Online jobs</b> across technology, business, finance, and other sectors to <b>GLA Online MBA placement</b> opportunities in management-oriented roles, the university\'s placement and career-support framework helps eligible learners connect with relevant job opportunities. GLA Online also provides a career counselling cell through which students can seek guidance on the type of jobs they should pursue and receive support from mentors and academic counsellors. Prospective applicants exploring GLA Online placements are also encouraged to review the GLA University Online fees for their chosen program before enrolling.\\n    </p>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- TABLE OF CONTENTS -->\\n<div style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4);display:flex;align-items:center;justify-content:center;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\">\\n        <line x1=\\\"8\\\" y1=\\\"6\\\" x2=\\\"21\\\" y2=\\\"6\\\"></line><line x1=\\\"8\\\" y1=\\\"12\\\" x2=\\\"21\\\" y2=\\\"12\\\"></line><line x1=\\\"8\\\" y1=\\\"18\\\" x2=\\\"21\\\" y2=\\\"18\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"6\\\" x2=\\\"3.01\\\" y2=\\\"6\\\"></line><line x1=\\\"3\\\" y1=\\\"12\\\" x2=\\\"3.01\\\" y2=\\\"12\\\"></line><line x1=\\\"3\\\" y1=\\\"18\\\" x2=\\\"3.01\\\" y2=\\\"18\\\"></line>\\n      </svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;\\\">Table of Contents</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;\\\">\\n      <a href=\\\"#placement-stats\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">1</span>\\n        Placement Highlights &amp; Career Outcomes\\n      </a>\\n      <a href=\\\"#recruiters\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">2</span>\\n        Top Recruiting Partners\\n      </a>\\n      <a href=\\\"#services\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">3</span>\\n        Career Acceleration Services\\n      </a>\\n      <a href=\\\"#faq\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-left:4px solid #9B1C2E;border-radius:10px;padding:12px;color:#0D1B2A;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#9B1C2E;color:#ffffff;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">4</span>\\n        FAQs\\n      </a>\\n    </div>\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:16px 0 0;\\\"></div>\\n  </div>\\n</div>\\n\\n<!-- PLACEMENT HIGHLIGHTS -->\\n<div id=\\\"placement-stats\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><circle cx=\\\"12\\\" cy=\\\"8\\\" r=\\\"6\\\"></circle><path d=\\\"M15.477 12.89L17 22l-5-3-5 3 1.523-9.11\\\"></path></svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Placement Highlights &amp; Career Outcomes</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      <b>GLA Online placement support</b> connects eligible online learners with career guidance and placement assistance through the university\'s placement ecosystem. The official GLA Online FAQ states that placement assistance is available to eligible students in the final semester, provided they meet the stated eligibility conditions. The university also publishes overall placement figures that indicate the broader reach of its career and recruitment network. These figures, including the average package and highest package reported each year, are part of the same GLA Online placements ecosystem available to eligible online learners.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:0 0 16px;justify-content:center;\\\">\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">₹6.30 LPA</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Overall Average CTC</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">₹60 LPA</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Highest CTC</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">86%</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Average Placement in 5 Years</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137, 44, 64, .14);border-radius:12px;padding:10px 14px;flex:1 1 80px;min-width:80px;max-width:160px;display:flex;flex-direction:column;align-items:flex-start;\\\">\\n        <div style=\\\"background:#f3d9dd;border-radius:20px;padding:2px 10px;margin-bottom:4px;\\\"><span style=\\\"font-size:clamp(11px,2.5vw,13px);font-weight:800;color:#7a1f2b;\\\">500+</span></div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#241014;padding-left:10px;\\\">Global Recruiters</div>\\n      </div>\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 14px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      These figures are published by GLA University as broader university-level placement benchmarks and should not be interpreted as online-program-specific salary guarantees. GLA University\'s current placement information reports a 60 LPA highest package, an overall average CTC of ₹6.30 LPA, an 86% average placement figure over the past five years, and a recruiter network of 500+ organisations. The GLA University Online average package and the GLA University Online highest package are drawn from the same institution-wide figures, since GLA Online\'s placement and career-support framework operates through GLA University\'s placement cell.\\n    </p>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      These outcomes sit within a broader <b>GLA Online career support</b> framework that spans career guidance and placement assistance. Programs such as <b>GLA Online MBA placement</b> benefit from the university\'s wider placement ecosystem, while BCA, BBA, B.Com, and MCA learners can access career support and placement assistance through the same institutional framework. GLA Online\'s programme pages specifically state that placements are powered by GLA University. Learners comparing the average package across programs can also check the applicable GLA University Online fees on the fees and courses page for full program cost details.\\n    </p>\\n\\n  </div>\\n</div>\\n\\n<!-- TOP RECRUITERS -->\\n<div id=\\\"recruiters\\\" style=\\\"background:#ffffff;border:1px solid rgba(122, 31, 43, .1);border-radius:18px;margin-bottom:28px;overflow:hidden;scroll-margin-top:30vh;\\\">\\n  <div style=\\\"height:5px;background:#9B1C2E;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(155,28,46,0.9),rgba(137,44,64,0.8),rgba(201,79,92,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#ffffff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><rect x=\\\"2\\\" y=\\\"4\\\" width=\\\"20\\\" height=\\\"16\\\" rx=\\\"2\\\"></rect><line x1=\\\"8\\\" y1=\\\"2\\\" x2=\\\"8\\\" y2=\\\"22\\\"></line><line x1=\\\"16\\\" y1=\\\"2\\\" x2=\\\"16\\\" y2=\\\"22\\\"></line><line x1=\\\"2\\\" y1=\\\"9\\\" x2=\\\"22\\\" y2=\\\"9\\\"></line><line x1=\\\"2\\\" y1=\\\"15\\\" x2=\\\"22\\\" y2=\\\"15\\\"></line></svg>\\n    </div>\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#241014;line-height:1.25;\\\">Top Recruiting Partners</h3>\\n  </div>\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#9B1C2E;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      The corporate network associated with <b>GLA University placement</b> outreach spans technology, consulting, banking, manufacturing, and other industries. Recruiters identified by the university include the following companies, part of the broader <b>GLA Online placements</b> ecosystem:\\n    </p>\\n\\n    <!-- Top Recruiting Partners -->\\n<div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:12px 0 4px;\\\">\\n\\n  <!-- Google -->\\n  <div style=\\\"width:110px;height:100px;border-radius:12px;background:#ffffff;border:1px solid #f3d9dd;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;cursor:default;transition:all 0.25s ease;box-shadow:0 4px 12px rgba(137,44,64,0.08);\\\" onmouseover=\\\"this.style.transform=\'translateY(-6px) scale(1.05)\';this.style.boxShadow=\'0 12px 30px rgba(137,44,64,0.25)\';this.style.borderColor=\'#9B1C2E\';\\\" onmouseout=\\\"this.style.transform=\'none\';this.style.boxShadow=\'0 4px 12px rgba(137,44,64,0.08)\';this.style.borderColor=\'#f3d9dd\';\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:8px;background:#faf8f9;border:1px solid rgba(137, 44, 64, .14);display:flex;align-items:center;justify-content:center;overflow:hidden;\\\">\\n      <img src=\\\"https://collegekeycms.geduconnect.in/uploads/Google.webp\\\" alt=\\\"Google\\\" style=\\\"width:40px;height:40px;object-fit:contain;\\\" onerror=\\\"this.style.display=\'none\';this.parentNode.innerHTML=\'&lt;span style=\\\\\'font-size:11px;font-weight:700;color:#9B1C2E;\\\\\'&gt;GOO&lt;/span&gt;\';\\\">\\n    </div>\\n    <div style=\\\"font-size:11px;font-weight:700;color:#0D1B2A;text-align:center;line-height:1.2;padding:0 4px;\\\">Google</div>\\n  </div>\\n\\n  <!-- Microsoft -->\\n  <div st