ads/clients/1770810906399.png',1,'Vivekananda Global University, Jaipur (VGU Online) is a premier NAAC A+ accredited and UGC-DEB entitled university offering flexible online UG and PG degree programs including Online MBA, MCA, BBA, BCA, and B.Com with placement support and 0% EMI payment options.','university','online','{\"location\":\"Sector 36, NRI Road, Jagatpura, Jaipur, Rajasthan 302017\",\"established\":\"2005\",\"naac_grade\":\"A+\",\"meta_title\":\"\",\"meta_description\":\"\",\"programs\":[1],\"approvals\":[1],\"affiliations\":[143,10],\"rankings\":[1,17,13,8],\"placement\":{\"highest_package\":\"\",\"average_package\":\"\",\"placement_rate\":\"\"},\"tabs\":[{\"id\":\"1789046530878\",\"title\":\"Overview\",\"slug\":\"overview\",\"content\":\"<h2>Vivekananda Global University Online - Introduction</h2>\\n\\n<!-- TABLE OF CONTENTS -->\\n<div style=\\\"background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;box-shadow:0 4px 18px rgba(95,29,43,0.05);\\\">\\n\\n  <div style=\\\"height:5px;background:linear-gradient(90deg,#5f1d2b,#892c40,#c9922a);\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#5f1d2b,#892c40);border:1px solid rgba(137,44,64,0.14);box-shadow:0 4px 16px rgba(137,44,64,0.22);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <line x1=\\\"8\\\" y1=\\\"6\\\" x2=\\\"21\\\" y2=\\\"6\\\"></line>\\n        <line x1=\\\"8\\\" y1=\\\"12\\\" x2=\\\"21\\\" y2=\\\"12\\\"></line>\\n        <line x1=\\\"8\\\" y1=\\\"18\\\" x2=\\\"21\\\" y2=\\\"18\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"6\\\" x2=\\\"3.01\\\" y2=\\\"6\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"12\\\" x2=\\\"3.01\\\" y2=\\\"12\\\"></line>\\n        <line x1=\\\"3\\\" y1=\\\"18\\\" x2=\\\"3.01\\\" y2=\\\"18\\\"></line>\\n      </svg>\\n    </div>\\n\\n    <div>\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Table of Contents</h3>\\n      <p style=\\\"margin:3px 0 0;font-size:12px;color:#6b7280;\\\">Explore VGU Online at a glance</p>\\n    </div>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;\\\">\\n\\n      <a href=\\\"#introduction\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">1</span>\\n        Introduction\\n      </a>\\n\\n      <a href=\\\"#highlights\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">2</span>\\n        Key Highlights\\n      </a>\\n\\n      <a href=\\\"#ranking\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">3</span>\\n        Ranking &amp; Awards\\n      </a>\\n\\n      <a href=\\\"#program-fees\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">4</span>\\n        Program &amp; Fees\\n      </a>\\n\\n      <a href=\\\"#admission-process\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">5</span>\\n        Admission Process\\n      </a>\\n\\n      <a href=\\\"#placement\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">6</span>\\n        Placement &amp; Career Support\\n      </a>\\n\\n      <a href=\\\"#student-support\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">7</span>\\n        Student Support\\n      </a>\\n\\n      <a href=\\\"#faq\\\" style=\\\"display:flex;align-items:center;gap:10px;flex:1 1 260px;min-width:260px;max-width:100%;box-sizing:border-box;text-decoration:none;background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:10px;padding:12px;color:#1a0a0f;font-size:14px;font-weight:500;\\\">\\n        <span style=\\\"background:#892c40;color:#fff;width:26px;height:26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;\\\">8</span>\\n        FAQs\\n      </a>\\n\\n    </div>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- INTRODUCTION -->\\n<div id=\\\"introduction\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;box-shadow:0 4px 18px rgba(95,29,43,0.04);\\\">\\n\\n  <div style=\\\"height:5px;background:#892c40;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#5f1d2b,#892c40);border:1px solid rgba(137,44,64,0.14);box-shadow:0 4px 16px rgba(137,44,64,0.22);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\">\\n        <path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path>\\n        <path d=\\\"M2 17l10 5 10-5\\\"></path>\\n        <path d=\\\"M2 12l10 5 10-5\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;line-height:1.25;\\\">Introduction</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;color:#1a0a0f;\\\">\\n      Vivekananda Global University Online (VGU Online) is the digital learning initiative of Vivekananda Global University,\\n      <a href=\\\"#\\\" style=\\\"color:#892c40;text-decoration:none;font-weight:600;\\\">Jaipur</a>,\\n      <a href=\\\"#\\\" style=\\\"color:#892c40;text-decoration:none;font-weight:600;\\\">Rajasthan</a>, delivered through the university\'s Centre for Distance and Online Education (CDOE). Also known as VGU Online Jaipur, it offers UGC-entitled degree programs designed for students, working professionals and learners who need flexible access to higher education. This VGU Online overview walks you through accreditation, courses, fees, admission and support, so you have what you need before applying.\\n    </p>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;color:#1a0a0f;\\\">\\n      VGU Online combines live webinars, recorded lectures, digital study material, e-books, quizzes, assignments and Learning Management System (LMS) access. Vivekananda Global University is <b>NAAC A+ accredited</b>, and its CDOE offers recognized Vivekananda Global University online courses in management, computer applications, humanities, journalism and mathematics.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:18px 0;justify-content:center;\\\">\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">NAAC A+</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;margin-top:3px;\\\">Accredited</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">9+</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;margin-top:3px;\\\">Online Programs</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">16,000+</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;margin-top:3px;\\\">Learners</div>\\n      </div>\\n\\n    </div>\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.12;margin:0 0 14px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;color:#1a0a0f;\\\">\\n      VGU Online currently offers <b>Online BBA, Online BCA, Online BA, Online MBA, Online MBA International Finance, Online MBA Digital Finance &amp; Accounting Analytics, Online MCA, Online M.Sc Mathematics, Online MA English and Online MA Journalism &amp; Mass Communication</b>. These VGU Online courses are structured for working professionals and full-time students alike.\\n    </p>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- KEY HIGHLIGHTS -->\\n<div id=\\\"highlights\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#c9922a;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#c9922a,#892c40);box-shadow:0 4px 16px rgba(201,146,42,0.22);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <path d=\\\"M12 2L15 8l6 .9-4.5 4.3L18 20l-6-3-6 3 1.5-6.8L3 8.9 9 8z\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Key Highlights</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      The table below covers the essentials every applicant should know before going deeper into <b>VGU Online</b> — from accreditation status to fees and the range of <b>Vivekananda Global University online courses</b> on offer.\\n    </p>\\n\\n    <div style=\\\"overflow-x:auto;\\\">\\n\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:360px;border:1px solid rgba(137,44,64,0.14);\\\">\\n\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:#5f1d2b;color:#fff;font-weight:700;font-size:13px;text-transform:uppercase;width:40%;\\\">Category</th>\\n            <th style=\\\"text-align:center;padding:14px 20px;background:#892c40;color:#fff;font-weight:700;font-size:13px;text-transform:uppercase;\\\">Details</th>\\n          </tr>\\n        </thead>\\n\\n        <tbody>\\n\\n          <tr>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">University</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Vivekananda Global University Online, offered via the Centre for Distance and Online Education (CDOE)</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">Location</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">VGU Online Jaipur, Rajasthan</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">Accreditation</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Vivekananda Global University is NAAC A+ accredited (valid until August 2027)</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">Regulatory Status</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">UGC-entitled online programs, recognized under Section 2(f) of the UGC Act, 1956</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">VGU Online Courses</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">9+ programs across management, computer applications, humanities, journalism &amp; mathematics</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);border-bottom:1px solid rgba(137,44,64,0.14);\\\">VGU Online Fees</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Approx. ₹24,000–₹75,000 per year depending on program (see Program &amp; Fees below)</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;font-weight:600;color:#1a0a0f;border-right:1px solid rgba(137,44,64,0.14);\\\">Learners</td>\\n            <td style=\\\"padding:13px 20px;font-size:13.5px;color:#6b7280;\\\">16,000+ enrolled across Vivekananda Global University online courses</td>\\n          </tr>\\n\\n        </tbody>\\n      </table>\\n\\n    </div>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- RANKING & AWARDS -->\\n<div id=\\\"ranking\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#c9922a;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#c9922a,#892c40);display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 4px 16px rgba(201,146,42,0.22);\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <path d=\\\"M12 2L15 8l6 .9-4.5 4.3L18 20l-6-3-6 3 1.5-6.8L3 8.9 9 8z\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Ranking &amp; Awards</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      Vivekananda Global University has built its academic credibility through consistent accreditation and institutional recognition, along with recognitions the university has referenced from bodies such as QS Asia and Outlook-ICARE (verify the latest category/year before citing these). Learners who complete a VGU Online degree receive it from Vivekananda Global University, which holds <b>NAAC A+ accreditation</b>.\\n    </p>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      To be precise about terminology: Vivekananda Global University itself is NAAC A+ accredited as an institution, and it offers UGC-entitled online degree programs through its CDOE, recognized under Section 2(f) of the UGC Act, 1956. Many applicants search for VGU Online UGC approved as shorthand for this — while the more accurate regulatory term is \\\"UGC-entitled,\\\" the online programs are sanctioned and valid for enrollment.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:12px;margin:18px 0;\\\">\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #892c40;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"NAAC\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\">NAAC <b>A+</b> Accredited</p>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #892c40;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"NAAC Score\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\">NAAC Accreditation Score: <b>3.29</b></p>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #892c40;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"NAAC Validity\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\">NAAC Accreditation Valid Until: <b>August 15, 2027</b></p>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #c9922a;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"UGC\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\">UGC Recognition: <b>Section 2(f)</b> of the UGC Act, 1956</p>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #c9922a;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"UGC\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\"><b>UGC-entitled</b> Online Degree Programs</p>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-top:3px solid #c9922a;border-radius:10px;padding:15px;width:145px;box-sizing:border-box;\\\">\\n        <img src=\\\"#\\\" alt=\\\"CDOE\\\" style=\\\"height:42px;width:42px;object-fit:contain;margin-bottom:9px;\\\">\\n        <p style=\\\"margin:0;font-size:11px;color:#1a0a0f;font-weight:600;\\\">Online Education Centre: <b>CDOE</b></p>\\n      </div>\\n\\n    </div>\\n\\n    <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-left:4px solid #c9922a;border-radius:12px;padding:16px 18px;\\\">\\n\\n      <p style=\\\"margin:0 0 8px;font-weight:700;color:#1a0a0f;font-size:14px;\\\">VGU Online NAAC Grade &amp; UGC Status, in Plain Terms</p>\\n\\n      <p style=\\\"margin:0;line-height:1.7;font-size:13.5px;color:#6b7280;\\\">\\n        The VGU Online NAAC grade that applicants ask about is the parent university\'s overall NAAC A+ rating — Vivekananda Global University\'s online division does not hold a separate NAAC grade of its own. Its online degree programs are UGC-entitled and delivered through the CDOE.\\n      </p>\\n\\n    </div>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- PROGRAM & FEES -->\\n<div id=\\\"program-fees\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#892c40;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#5f1d2b,#892c40);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <path d=\\\"M9 11l3 3L22 4\\\"></path>\\n        <path d=\\\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Program &amp; Fees</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      VGU Online offers undergraduate and postgraduate degree programs in management, computer applications, humanities, journalism and mathematics, delivered through the university\'s LMS with live classes, recorded lectures, assignments and online assessments. This section covers VGU Online courses and fees so you know what to expect before applying to any Vivekananda Global University online courses.\\n    </p>\\n\\n<h4 style=\\\"color:#1a0a0f;margin:16px 0 8px;font-weight:700;\\\">Program &amp; Fee Facts</h4>\\n\\n<ul style=\\\"list-style-type:disc !important;list-style-position:outside !important;padding-left:24px !important;margin:0 0 16px 0 !important;line-height:1.8;color:#1a0a0f;\\\">\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Undergraduate programs:</b> Online BA, Online BBA and Online BCA\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Postgraduate programs:</b> Online MBA, Online MCA, Online M.Sc Mathematics, Online MA English and Online MA Journalism &amp; Mass Communication\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Specialized programs:</b> Online MBA International Finance and Online MBA Digital Finance &amp; Accounting Analytics\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Learning mode:</b> Online through LMS-based live sessions, recorded lectures and self-learning material\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;\\\">\\n    <b>Fee payment:</b> Semester, annual or one-time payment options may be available depending on the program\\n  </li>\\n\\n</ul>\\n\\n    <h4 style=\\\"color:#1a0a0f;margin-bottom:8px;\\\">Program Fees</h4>\\n\\n    <div style=\\\"overflow-x:auto;\\\">\\n\\n      <table style=\\\"width:100%;border-collapse:collapse;min-width:500px;border:1px solid rgba(137,44,64,0.14);margin-bottom:14px;\\\">\\n\\n        <thead>\\n          <tr>\\n            <th style=\\\"text-align:center;padding:12px 16px;background:#5f1d2b;color:#fff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Program</th>\\n            <th style=\\\"text-align:center;padding:12px 16px;background:#892c40;color:#fff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Duration</th>\\n            <th style=\\\"text-align:center;padding:12px 16px;background:#5f1d2b;color:#fff;font-weight:700;font-size:12.5px;text-transform:uppercase;\\\">Annual Fee</th>\\n          </tr>\\n        </thead>\\n\\n        <tbody>\\n\\n          <tr>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online BA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">3 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹24,000*</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online BBA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">3 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹44,000*</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online BCA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">3 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹44,000*</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online MA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">2 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹36,000*</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online MBA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">2 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹75,000*</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online M.Sc.</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">2 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹36,000*</td>\\n          </tr>\\n\\n          <tr>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">Online MCA</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">2 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;border-bottom:1px solid rgba(137,44,64,0.14);\\\">₹75,000*</td>\\n          </tr>\\n\\n          <tr style=\\\"background:#fdf0f2;\\\">\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">Online MA Journalism &amp; Mass Communication (MAJMC)</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">2 Years</td>\\n            <td style=\\\"padding:11px 16px;font-size:13px;text-align:center;\\\">₹36,000*</td>\\n          </tr>\\n\\n        </tbody>\\n      </table>\\n\\n    </div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      VGU Online fees vary by course, specialization and payment plan, with semester, annual or one-time options generally available. Compare the total VGU Online fees for your shortlisted VGU Online degree before enrolling, since amounts can change by admission cycle.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/vgu-online/program-fees\\\" style=\\\"display:inline-block;background:#892c40;color:#fff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;box-shadow:0 4px 12px rgba(137,44,64,0.18);\\\">\\n      Check VGU Online Programs &amp; Fees →\\n    </a>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- ADMISSION PROCESS -->\\n<div id=\\\"admission-process\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#892c40;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#892c40,#5f1d2b);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <path d=\\\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\\\"></path>\\n        <polyline points=\\\"9 22 9 12 15 12 15 22\\\"></polyline>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Admission Process</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      VGU Online follows a fully digital admission process: eligible candidates choose a program, register online, fill in the application form, upload documents and pay the applicable fee without visiting campus. This is useful for applicants who\'ve been researching this VGU Online overview before deciding to apply.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:18px 0;justify-content:center;\\\">\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">100%</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Application Mode</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">Merit</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Selection Basis</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:17px;font-weight:800;color:#892c40;\\\">Digital</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Document Upload</div>\\n      </div>\\n\\n    </div>\\n\\n<h4 style=\\\"color:#1a0a0f;margin:16px 0 8px;font-weight:700;\\\">Admission Process Facts</h4>\\n\\n<ul style=\\\"list-style-type:disc !important;list-style-position:outside !important;padding-left:24px !important;margin:0 0 16px 0 !important;line-height:1.8;color:#1a0a0f;\\\">\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Step 1:</b> Select the preferred online program and complete registration\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Step 2:</b> Fill in personal and academic details and upload the required documents\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;\\\">\\n    <b>Step 3:</b> Pay the applicable program fee and wait for document verification and admission confirmation\\n  </li>\\n\\n</ul>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      Undergraduate programs generally require Class 12 (or equivalent), while postgraduate programs require a relevant bachelor\'s degree — exact eligibility and document requirements vary by course and should be checked before submitting the application.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/vgu-online/admission-process\\\" style=\\\"display:inline-block;background:#892c40;color:#fff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">\\n      Check VGU Online Admission Process →\\n    </a>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- PLACEMENT & CAREER SUPPORT -->\\n<div id=\\\"placement\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#c9922a;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#5f1d2b,#c9922a);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <circle cx=\\\"12\\\" cy=\\\"8\\\" r=\\\"6\\\"></circle>\\n        <path d=\\\"M15.477 12.89L17 22l-5-3-5 3 1.523-9.11\\\"></path>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Placement &amp; Career Support</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      VGU Online follows a career-oriented approach that helps students and working professionals strengthen industry-relevant knowledge and professional skills, offering employability guidance, mentorship and access to a network the university describes as 500+ hiring partners.\\n    </p>\\n\\n<h4 style=\\\"color:#1a0a0f;margin:16px 0 8px;font-weight:700;\\\">Placement &amp; Career Support Facts</h4>\\n\\n<ul style=\\\"list-style-type:disc !important;list-style-position:outside !important;padding-left:24px !important;margin:0 0 16px 0 !important;line-height:1.8;color:#1a0a0f;\\\">\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Career assistance:</b> Employability guidance and professional skill development for online learners\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Industry readiness:</b> Career-oriented curriculum, mentorship and practical learning support\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;\\\">\\n    <b>Hiring network:</b> The university highlights a network of 500+ hiring partners\\n  </li>\\n\\n</ul>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:8px;margin:16px 0;\\\">\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#892c40;border:1px solid rgba(137,44,64,0.14);\\\">Career Guidance</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#892c40;border:1px solid rgba(137,44,64,0.14);\\\">Expert Mentorship</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fdf0f2;color:#892c40;border:1px solid rgba(137,44,64,0.14);\\\">Skill Development</span>\\n\\n      <span style=\\\"font-size:11px;font-weight:700;padding:5px 12px;border-radius:30px;background:#fff8e9;color:#9b6b13;border:1px solid rgba(201,146,42,0.25);\\\">Industry Readiness</span>\\n\\n    </div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      Placement and career outcomes depend on the selected program, specialization, previous experience, academic performance, skills and recruitment conditions — no individual job, salary or placement outcome should be considered guaranteed.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/vgu-online/placement-career-support\\\" style=\\\"display:inline-block;background:#892c40;color:#fff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">\\n      Explore VGU Online Placement &amp; Career Support →\\n    </a>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- STUDENT SUPPORT -->\\n<div id=\\\"student-support\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:#892c40;\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#892c40,#5f1d2b);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <rect x=\\\"2\\\" y=\\\"7\\\" width=\\\"20\\\" height=\\\"14\\\" rx=\\\"2\\\"></rect>\\n        <path d=\\\"M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2\\\"></path>\\n        <line x1=\\\"12\\\" y1=\\\"12\\\" x2=\\\"12\\\" y2=\\\"16\\\"></line>\\n        <line x1=\\\"10\\\" y1=\\\"14\\\" x2=\\\"14\\\" y2=\\\"14\\\"></line>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">Student Support</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      VGU Online provides academic and technical support so learners can manage their studies remotely, with LMS access to classes, recordings, e-books, assignments and quizzes. This part of the VGU Online overview shows how VGU Online Jaipur supports every learner enrolled in VGU Online courses, regardless of location.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:10px;margin:18px 0;justify-content:center;\\\">\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:16px;font-weight:800;color:#892c40;\\\">LMS</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Learning Access</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:16px;font-weight:800;color:#892c40;\\\">Live + Recorded</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Online Classes</div>\\n      </div>\\n\\n      <div style=\\\"background:#fdf0f2;border:1px solid rgba(137,44,64,0.14);border-radius:12px;padding:12px 14px;flex:1 1 100px;min-width:100px;max-width:170px;text-align:center;\\\">\\n        <div style=\\\"font-size:16px;font-weight:800;color:#892c40;\\\">Online</div>\\n        <div style=\\\"font-size:11px;font-weight:600;color:#6b7280;\\\">Learner Assistance</div>\\n      </div>\\n\\n    </div>\\n\\n<h4 style=\\\"color:#1a0a0f;margin:16px 0 8px;font-weight:700;\\\">Student Support Facts</h4>\\n\\n<ul style=\\\"list-style-type:disc !important;list-style-position:outside !important;padding-left:24px !important;margin:0 0 16px 0 !important;line-height:1.8;color:#1a0a0f;\\\">\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    Live webinars and recorded lectures support flexible learning and revision\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    Digital study material, e-books, assignments and quizzes are accessible through the LMS\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;margin-bottom:4px;\\\">\\n    <b>Academic support:</b> Faculty guidance and query resolution\\n  </li>\\n\\n  <li style=\\\"display:list-item !important;list-style-type:disc !important;\\\">\\n    <b>Technical support:</b> Assistance with LMS access and login issues\\n  </li>\\n\\n</ul>\\n\\n    <p style=\\\"line-height:1.7;color:#1a0a0f;\\\">\\n      The online support system is designed for learners studying from different locations and for working professionals balancing education with other responsibilities. The exact support channels, response times and services may vary according to university policy and the selected program.\\n    </p>\\n\\n    <a href=\\\"https://geduconnect.com/university/vgu-online/student-support\\\" style=\\\"display:inline-block;background:#892c40;color:#fff;padding:10px 20px;border-radius:9px;text-decoration:none;font-size:13px;font-weight:700;margin-top:18px;\\\">\\n      Explore VGU Online Student Support →\\n    </a>\\n\\n  </div>\\n</div>\\n\\n\\n<!-- FAQs -->\\n<div id=\\\"faq\\\" style=\\\"scroll-margin-top:30vh;background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n\\n  <div style=\\\"height:5px;background:linear-gradient(90deg,#5f1d2b,#892c40,#c9922a);\\\"></div>\\n\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#5f1d2b,#892c40);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\">\\n        <circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"></circle>\\n        <path d=\\\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\\\"></path>\\n        <line x1=\\\"12\\\" y1=\\\"17\\\" x2=\\\"12.01\\\" y2=\\\"17\\\"></line>\\n      </svg>\\n    </div>\\n\\n    <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;\\\">FAQs</h3>\\n\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.14;margin:0 0 16px;\\\"></div>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        1. What is VGU Online?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        VGU Online is the digital learning initiative of Vivekananda Global University Online, delivered through its Centre for Distance and Online Education (CDOE). It offers UGC-entitled online degree programs for students and working professionals through live classes, recorded lectures and LMS-based study material.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        2. Is VGU Online UGC approved?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        Vivekananda Global University\'s online programs are recognized under Section 2(f) of the UGC Act, 1956, and are more precisely described as UGC-entitled. Many applicants still search for VGU Online UGC approved, and functionally, yes — the online degrees are sanctioned and valid, offered by a university that is NAAC A+ accredited.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        3. Which VGU Online courses are available?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        VGU Online offers 9+ programs — Online BA, BBA, BCA, MBA, MBA International Finance, MBA Digital Finance &amp; Accounting Analytics, MCA, M.Sc Mathematics, MA English and MA Journalism &amp; Mass Communication — across Vivekananda Global University online courses at both UG and PG level.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        4. How much are VGU Online fees?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        VGU Online fees range roughly from ₹24,000 to ₹75,000 per year depending on the program, with semester, annual or one-time payment options generally available. Confirm the current VGU Online fees for your chosen program before applying.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        5. Where is VGU Online located?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        VGU Online is operated from VGU Online Jaipur, Rajasthan. Since programs are fully online, learners can study from anywhere in India without relocating.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        6. Is a VGU Online degree valid?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        A VGU Online degree is issued by Vivekananda Global University through its UGC-entitled CDOE programs, so it carries recognized standing for further study and employment, subject to the specific requirements of the employer or institution involved.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #892c40;border-radius:12px;margin-bottom:10px;background:#fdf0f2;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        7. What is the VGU Online NAAC grade?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        There\'s no separate NAAC grade for the online division. The VGU Online NAAC grade applicants refer to is Vivekananda Global University\'s overall NAAC A+ accreditation, which covers the institution as a whole, including programs delivered through CDOE.\\n      </div>\\n    </details>\\n\\n\\n    <details style=\\\"border:1px solid rgba(137,44,64,0.14);border-left:4px solid #c9922a;border-radius:12px;background:#fff8e9;overflow:hidden;\\\">\\n      <summary style=\\\"cursor:pointer;padding:15px 16px;font-weight:600;color:#1a0a0f;font-size:14px;\\\">\\n        8. What is the eligibility for VGU Online admission?\\n      </summary>\\n      <div style=\\\"padding:0 16px 16px 16px;font-size:13.5px;color:#6b7280;line-height:1.8;\\\">\\n        Undergraduate VGU Online courses generally require Class 12 or an equivalent qualification; postgraduate programs require a relevant bachelor\'s degree. Exact eligibility varies by course, so check the specific program page before applying.\\n      </div>\\n    </details>\\n\\n  </div>\\n</div>\"},{\"id\":\"1789468372622\",\"title\":\"Program & Fees\",\"slug\":\"program-fees\",\"content\":\"<!-- VGU ONLINE FEES -->\\n<div style=\\\"background:#fff;border:1px solid rgba(137,44,64,0.14);border-radius:18px;margin-bottom:28px;overflow:hidden;\\\">\\n  <div style=\\\"height:5px;background:#892c40;border-radius:18px 18px 0 0;\\\"></div>\\n  <div style=\\\"display:flex;align-items:center;gap:12px;padding:20px 20px 0;\\\">\\n    <div style=\\\"width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(137,44,64,0.9),rgba(95,29,43,0.8),rgba(201,146,42,0.7));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.3);box-shadow:0 4px 16px rgba(137,44,64,0.4),inset 0 1px 0 rgba(255,255,255,0.35);display:flex;align-items:center;justify-content:center;flex-shrink:0;\\\">\\n      <svg width=\\\"22\\\" height=\\\"22\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"#fff\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\" style=\\\"filter:drop-shadow(0 1px 3px rgba(255,255,255,0.4));\\\"><path d=\\\"M12 2L2 7l10 5 10-5-10-5z\\\"></path><path d=\\\"M2 17l10 5 10-5\\\"></path><path d=\\\"M2 12l10 5 10-5\\\"></path></svg>\\n    </div>\\n    <div style=\\\"flex:1;min-width:0;\\\">\\n      <h3 style=\\\"margin:0;font-size:clamp(15px,3vw,19px);font-weight:700;color:#1a0a0f;line-height:1.25;\\\">Vivekananda Global University Online — Courses &amp; Fees 2026</h3>\\n    </div>\\n  </div>\\n\\n  <div style=\\\"padding:16px 20px 24px;\\\">\\n    <div style=\\\"height:1px;background:#892c40;opacity:0.15;margin:0 0 16px;\\\"></div>\\n\\n    <p style=\\\"line-height:1.7;word-spacing:normal;text-align:left;word-break:break-word;\\\">\\n      This <b>VGU Online courses and fees</b> guide covers <b>VGU Online UG courses</b> and <b>VGU Online PG courses</b> offered through the Centre for Distance and Online Education (CDOE), with <b>VGU Online fees</b> payable per semester or per year. Below you will find detailed <b>VGU Online program fees</b> for every course, including <b>VGU Online BA fees</b>, <b>VGU Online BBA fees</b>, <b>VGU Online BCA fees</b>, <b>VGU Online MBA fees</b>, and <b>VGU Online MCA fees</b>. Students should confirm the latest applicable <b>Vivekananda Global University Online fees</b>, scholarship eligibility, and payment schedule before enrolling, as amounts may vary by admission cycle.\\n    </p>\\n\\n    <div style=\\\"display:flex;flex-wrap:wrap;gap:14px;\\\">\\n\\n      <!-- BA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137,44,64,0.14);border-top:4px solid #892c40;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#892c40;margin-bottom:6px;\\\">Online BA · 3 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#1a0a0f;margin-bottom:10px;\\\">BA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#fff;color:#892c40;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137,44,64,0.14);\\\">Reg. Fee ₹1,000</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#892c40;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid rgba(137,44,64,0.14);\\\">₹24,000/yr</span>\\n          <span style=\\\"display:inline-block;background:rgba(201,146,42,0.10);color:#c9922a;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid rgba(201,146,42,0.25);\\\">Total ₹81,000</span>\\n        </div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;\\\">\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#fff;text-decoration:none;font-weight:600;background:#892c40;padding:6px 14px;border-radius:9px;\\\">View Course</a>\\n          <a href=\\\"#\\\" style=\\\"font-size:13px;color:#892c40;text-decoration:none;font-weight:600;background:#fff;padding:6px 14px;border-radius:9px;border:1px solid rgba(137,44,64,0.14);\\\">Fee Details</a>\\n        </div>\\n      </div>\\n\\n      <!-- BBA -->\\n      <div style=\\\"width:calc(50% - 7px);box-sizing:border-box;border:1px solid rgba(137,44,64,0.14);border-top:4px solid #892c40;border-radius:12px;padding:18px 16px;background:#fdf0f2;transition:box-shadow 0.2s,transform 0.2s;\\\" onmouseover=\\\"this.style.boxShadow=\'0 8px 24px rgba(137,44,64,0.15)\';this.style.transform=\'translateY(-3px)\'\\\" onmouseout=\\\"this.style.boxShadow=\'none\';this.style.transform=\'translateY(0)\'\\\">\\n        <div style=\\\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:#892c40;margin-bottom:6px;\\\">Online BBA · 3 Years</div>\\n        <div style=\\\"font-size:16px;font-weight:700;color:#1a0a0f;margin-bottom:10px;\\\">BBA</div>\\n        <div style=\\\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;\\\">\\n          <span style=\\\"display:inline-block;background:#fff;color:#892c40;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid rgba(137,44,64,0.14);\\\">Reg. Fee ₹1,000</span>\\n          <span style=\\\"display:inline-block;background:#fdf0f2;color:#892c40;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid rgba(137,44,64,0.14);\\\">₹44,000/yr</span>\\n          <span style=\\\"display:inline-block;background:rgba(201,146,42,0.10);color:#c9922a;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;border:1px solid rgba(201,146,42,0.25);\\\">Total ₹1,41,000</span>\\n        </div>\\n        <div style=\\\"disp