INSERT INTO `services` VALUES (2,'End-to-End Admission Support','At GeduConnect, we provide complete End-to-End Admission Support for students, education consultants, coaching institutes, and admission partners across India. Our streamlined admission process helps simplify Online, Distance, and Regular Degree admissions with expert guidance at every stage.\r\nFrom student counseling and course selection to documentation, application processing, verification, and final enrollment, our dedicated support team ensures a smooth and hassle-free admission experience.\r\nWhether you are an independent counselor or an established education consultancy, GeduConnect offers reliable backend support to help you manage admissions efficiently and professionally.\r\n','/uploads/services/1779436765205-101419905.webp','/uploads/services/1779292616761-156990318.png',2,1,'2026-02-11 07:09:48','2026-05-30 08:37:21','end-to-end-admission-support',NULL,NULL,NULL,'<!-- GeduConnect | Admission Support Service | Mobile-Responsive | CKEditor Safe -->\r\n\r\n<style>\r\n@media (max-width: 768px) {\r\n  .gec-grid-3   { grid-template-columns: 1fr !important; }\r\n  .gec-grid-4   { grid-template-columns: 1fr 1fr !important; gap: 14px !important; }\r\n  .gec-grid-5   { grid-template-columns: 1fr 1fr !important; gap: 16px !important; }\r\n  .gec-grid-2   { grid-template-columns: 1fr !important; gap: 32px !important; }\r\n  .gec-faq-grid { grid-template-columns: 1fr !important; }\r\n  .gec-sec-pad  { padding: 52px 16px !important; }\r\n  .gec-sec-dark { padding: 52px 16px !important; }\r\n  .gec-who-card { padding: 28px 20px !important; transform: none !important; }\r\n  .gec-who-badge { display: none !important; }\r\n  .gec-card-3d  { transform: none !important; }\r\n  .gec-step-line { display: none !important; }\r\n  .gec-cta-btns { flex-direction: column !important; align-items: center !important; }\r\n  .gec-cta-btns a { width: 100% !important; max-width: 320px !important; text-align: center !important; box-sizing: border-box !important; padding-left: 16px !important; padding-right: 16px !important; }\r\n  .gec-faq-footer { flex-direction: column !important; align-items: center !important; }\r\n  .gec-faq-footer a { width: 100% !important; max-width: 320px !important; justify-content: center !important; box-sizing: border-box !important; }\r\n  .gec-process-circle { width: 72px !important; height: 72px !important; font-size: 22px !important; transform: none !important; }\r\n  .gec-process-title  { font-size: 14px !important; }\r\n  .gec-process-desc   { font-size: 11px !important; }\r\n}\r\n@media (max-width: 480px) {\r\n  .gec-grid-4 { grid-template-columns: 1fr !important; }\r\n  .gec-grid-5 { grid-template-columns: 1fr !important; }\r\n  .gec-who-tags { gap: 8px !important; }\r\n}\r\n</style>\r\n\r\n\r\n<!-- ═══════════════════════════════════════\r\n     WHY CHOOSE US\r\n═══════════════════════════════════════ -->\r\n<section class=\"gec-sec-pad\" style=\"background:linear-gradient(180deg,#faf8f5 0%,#f3ede0 100%);padding:72px 20px;font-family:\'Inter\',sans-serif;border-top:1px solid rgba(122,31,43,0.1);\">\r\n  <div style=\"text-align:center;max-width:700px;margin:0 auto 48px;\">\r\n    <span style=\"display:inline-block;font-size:11px;font-weight:700;color:#c9922a;letter-spacing:0.28em;text-transform:uppercase;margin-bottom:14px;\">Why Choose Us</span>\r\n    <h2 style=\"font-family:\'Cormorant Garamond\',Georgia,serif;font-size:clamp(26px,3.5vw,44px);font-weight:700;color:#14070b;line-height:1.15;margin:0 0 14px;\">Why Choose Our Admission Support?</h2>\r\n    <div style=\"width:64px;height:3px;background:linear-gradient(90deg,#7a1f2b,#c9922a);margin:0 auto 18px;border-radius:2px;\"></div>\r\n    <p style=\"font-size:15px;line-height:1.65;color:#6b7280;margin:0;\">Trusted by consultants and students across India for reliable, end-to-end admission assistance.</p>\r\n  </div>\r\n\r\n  <div class=\"gec-grid-3\" style=\"max-width:1140px;margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr);gap:24px;\">\r\n\r\n    <div class=\"gec-card-3d\" style=\"background:#ffffff;border-radius:18px;padding:28px 22px 24px;border:1px solid rgba(122,31,43,0.08);box-shadow:0 10px 30px rgba(0,0,0,0.06);position:relative;overflow:hidden;transform:perspective(800px) rotateX(2deg) rotateY(-2deg);\">\r\n      <div style=\"position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,#7a1f2b,#c9922a);\"></div>\r\n      <div style=\"width:56px;height:56px;border-radius:14px;background:linear-gradient(135deg,rgba(122,31,43,0.1),rgba(201,146,42,0.16));display:flex;align-items:center;justify-content:center;margin-bottom:18px;font-size:26px;\">📋</div>\r\n      <h3 style=\"font-family:\'Cormorant Garamond\',Georgia,serif;font-size:20px;font-weight:700;color:#14070b;margin:0 0 10px;line-height:1.25;\">Complete Admission Assistance</h3>\r\n      <p style=\"font-size:13px;line-height:1.65;color:#6b7280;margin:0;\">Full support for counseling, application submission, documentation verification, fee guidance, and enrollment coordination.</p>\r\n    </div>\r\n\r\n    <div class=\"gec-card-3d\" style=\"background:#ffffff;border-radius:18px;padding:28px 22px 24px;border:1px solid rgba(122,31,43,0.08);box-shadow:0 10px 30px rgba(0,0,0,0.06);position:relative;overflow:hidden;transform:perspective(800px) rotateX(2deg) rotateY(0deg);\">\r\n      <div style=\"position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,#7a1f2b,#c9922a);\"></div>\r\n      <div style=\"width:56px;height:56px;border-radius:14px;background:linear-gradient(135deg,rgba(122,31,43,0.1),rgba(201,146,42,0.16));display:flex;align-items:center;justify-content:center;margin-bottom:18px;font-size:26px;\">🏛️</div>\r\n      <h3 style=\"font-family:\'Cormorant Garamond\',Georgia,serif;font-size:20px;font-weight:700;color:#14070b;margin:0 0 10px;line-height:1.25;\">Access to Top Universities</h3>\r\n      <p style=\"font-size:13px;line-heig